// Next.js instrumentation hook. Generated by `eos scaffold otel-node`; yours to edit.
// Next.js calls register() once per server instance. The Node SDK does not run on the edge runtime, so
// it is imported only for the Node.js runtime (https://nextjs.org/docs/app/guides/open-telemetry).
// Needs Vercel? `@vercel/otel` (registerOTel) also covers edge; this manual setup stays vendor-neutral.
export async function register() {
  if (process.env.NEXT_RUNTIME === "nodejs") {
    await import("./instrumentation.node");
  }
}
